rt13_sr3.py.text:
"""RT-13. SR-3 (a dropped ladder cell: 'nothing is classified NEG or LEAD')
against the committed families.stage3, dry-called on HAND-BUILT synthetic
rows (a control-flow test, not a measurement), with est.LADDER and
est.LEAD_ALPHABET pointed at synthetic cell names."""
import json, sys
sys.path.insert(0, sys.argv[1])
import estimator as est
import families as fam

est.LADDER = ("SYN-K13", "SYN-K19", "SYN-K23")
est.LEAD_ALPHABET = {"SYN-K13": 16, "SYN-K19": 64, "SYN-K23": 128}
ns = {"q50": 6.0, "q99": 7.0, "W": 1.0, "V": [0.5] * 10, "draws": 500}

def null_rows():
    # a null-like arm: E_Sh about 0, rank p not at its floor, estimated
    rows = []
    for s in range(10):
        g = 6.0 + 0.01 * s
        rows.append({"seed": s, "G": g, "E_RL": g - 6.0, "E_Sh": 0.01 * (s - 5), "p": 6.0 / 11,
                     "V": 0.5, "Z": 0.02 * (s - 5), "used": 100, "excluded": 0, "estimated": True})
    return rows

full = {"SYN-K13": {}, "SYN-K19": {}, "SYN-K23": {}, "SYN-K41": {}}
for cid, Ms in (("SYN-K13", (16, 8)), ("SYN-K19", (64, 16)), ("SYN-K23", (128, 32, 16)), ("SYN-K41", (16,))):
    for M in Ms:
        for name in ("F2@0", "RLFAM", "XCO1", "XCO2"):
            full[cid][(name, M)] = {"rows": null_rows(), "null": ns}
res = {}
v = fam.stage3(full, [11.0, 17.0, 21.0])
res["all_ladder_cells_present"] = {k: v["verdicts"][k]["verdict"] for k in v["verdicts"]}
dropped = {k: val for k, val in full.items() if not (k == "SYN-K23")}
v = fam.stage3(dropped, [11.0, 17.0, 21.0])
res["ladder_cell_SYN_K23_dropped"] = {k: (v["verdicts"][k]["verdict"], v["verdicts"][k].get("ladder")) for k in v["verdicts"]}
res["ladder_cell_SYN_K23_dropped_PC15_PC17"] = (v["PC-15"], v["PC-17"])
lead_key_removed = {k: dict(val) for k, val in full.items()}
for name in ("F2@0", "RLFAM", "XCO1", "XCO2"):
    del lead_key_removed["SYN-K23"][(name, 128)]
v = fam.stage3(lead_key_removed, [11.0, 17.0, 21.0])
res["lead_key_SYN_K23_at_128_removed_as_invalid"] = {k: (v["verdicts"][k]["verdict"], v["verdicts"][k].get("ladder")) for k in v["verdicts"]}
print(json.dumps(res, indent=1))

rt4_np.py.text:
"""RT-4 (numpy path). J3 item (ii) and PTM-E: a uniform random label (RLFAM),
XCO1 and XCO2 of every declared cell's shape (NON-DECLARED groups Z/(q l')),
at the declared alphabets and S, ten seeds, read exactly as family arms
(stratified shuffles, exact-saturated null, per-seed widths), classified by
the committed est.classify_family over the three lead keys. R replicates."""
import json, math, sys, time
sys.path.insert(0, sys.argv[1])
sys.path.insert(0, sys.argv[2])
import estimator as est
import syn

R = int(sys.argv[3])
SHAPES = {"SYN-K13": (2011, 4, 13, (16, 8)), "SYN-K19": (130927, 4, 19, (64, 16)),
          "SYN-K23": (2095867, 4, 23, (128, 32, 16)), "SYN-K41": (549756390949, 4, 41, (16,)),
          "SYN-O19": (261847, 2, 19, (64, 16))}
LEAD = [("SYN-K13", 16), ("SYN-K19", 64), ("SYN-K23", 128)]
LOG2 = [math.log2(2011), math.log2(130927), math.log2(2095867)]
t0 = time.time()
out = {"replicates": []}
for rep in range(R):
    cells = {"RLFAM": {}, "XCO1": {}, "XCO2": {}}
    per = {}
    for cid, (l, q, n, Ms) in SHAPES.items():
        for M in Ms:
            S = est.S_of(M)
            nulls, reads = [], {k: [] for k in cells}
            for s in range(10):
                st = syn.make_stream(q * l, S, syn.rng_of("rt4np", rep, cid, M, s))
                U = syn.support(st, S)
                e = st["pts"][:U] % q
                nulls.append(syn.null_np(st, S, U, M, syn.rng_of("rt4np-null", rep, cid, M, s), 50, e, q))
                rng = syn.rng_of("rt4np-lab", rep, cid, M, s)
                labs = {"RLFAM": syn.random_labels_np(U, M, rng),
                        "XCO1": syn.xco1_np(U, n, M, e, rng),
                        "XCO2": syn.xco2_np(U, M, e, q, rng)}
                for k, lab in labs.items():
                    reads[k].append(syn.read_arm_np(st, S, U, lab, M, syn.rng_of("rt4np-sh", rep, cid, M, s, k), e))
            ns = est.summarize_null(nulls)
            for k in cells:
                rows = est.seed_rows(reads[k], ns, ns["V"])
                cells[k][(cid, M)] = {"rows": rows, "null": ns}
                per["%s@%d/%s" % (cid, M, k)] = {
                    "estimated": est.estimated(rows), "L1": est.estimated(rows) and est.clause_L1(rows, ns),
                    "L3": est.estimated(rows) and est.clause_L3(rows, ns),
                    "median_E_Sh_over_W": round(est.median([r["E_Sh"] for r in rows]) / ns["W"], 3),
                    "median_E_RL_over_W": round(est.median([r["E_RL"] for r in rows]) / ns["W"], 3),
                    "rank_floor_seeds": sum(1 for r in rows if r["p"] <= 1.0 / 11 + 1e-12)}
            per["%s@%d/null" % (cid, M)] = {"q50": ns["q50"], "q99": ns["q99"], "W": ns["W"], "median_V": est.median(ns["V"]), "min_V": min(ns["V"])}
    verdicts = {k: est.classify_family(v, LEAD, LOG2)["verdict"] for k, v in cells.items()}
    out["replicates"].append({"verdicts": verdicts, "per_cell": per})
    print("rep", rep, verdicts, round(time.time() - t0), flush=True)
out["summary"] = {k: {v: sum(1 for r in out["replicates"] if r["verdicts"][k] == v) for v in ("NEG", "ART-RES", "LEAD", "NOT-ESTIMATED")} for k in ("RLFAM", "XCO1", "XCO2")}
out["seconds"] = round(time.time() - t0, 1)
json.dump(out, open(sys.argv[4], "w"), default=str)
print("done", out["summary"], out["seconds"])

rt_np.py.text:
"""RT-5, RT-6n, RT-7, RT-9: numpy measurement (syn.py, gain bit-exact with
the committed estimator.gain) on NON-DECLARED synthetic groups; every decision
is made by the committed CODE-EST functions (seed_rows, summarize_null,
clause_L1, clause_L3, clause_L2, classify_family) and CODE-FAM
heur_b2_held_out. Usage: rt_np.py IMPL SCRIPTS MODE OUT [args]."""
import json, math, sys, time
import numpy as np
sys.path.insert(0, sys.argv[1])
sys.path.insert(0, sys.argv[2])
import estimator as est
import families as fam
import syn

MODE, OUT = sys.argv[3], sys.argv[4]
L13, L19, L23, L41, LO19 = 2011, 130927, 2095867, 549756390949, 261847
LOG2 = [math.log2(L13), math.log2(L19), math.log2(L23)]
RHOS = (1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.25, 0.125, 0.0625)


def rkey(pts, l, M):
    """Rounded log-interval key, round(i M / l) mod M (a sharper approximate
    filter than the floor key: max conditional sum-label mass about 3/4)."""
    r = pts % l
    return ((2 * r * M + l) // (2 * l)) % M


def measure(N, q, l, M, seed_list, label_fns, tag, null=True, draws=50):
    """Per seed: one stream; the null (saturated with q > 1, uniform with
    q == 1); every label read with R_SH shuffles (stratified iff q > 1).
    Returns (null summary, {name: rows})."""
    S = est.S_of(M)
    null_by_seed, reads = [], {}
    for s in seed_list:
        st = syn.make_stream(N, S, syn.rng_of(tag, "stream", N, M, s))
        U = syn.support(st, S)
        pts = st["pts"][:U]
        e = (pts % q) if q > 1 else None
        rng = syn.rng_of(tag, "lab", N, M, s)
        if null:
            null_by_seed.append(syn.null_np(st, S, U, M, syn.rng_of(tag, "null", N, M, s), draws, e, q))
        for name, fn in label_fns.items():
            lab = fn(pts, e, U, rng)
            reads.setdefault(name, []).append(syn.read_arm_np(st, S, U, lab, M, syn.rng_of(tag, "sh", name, N, M, s), e))
    ns = est.summarize_null(null_by_seed) if null else None
    rows = {k: est.seed_rows(v, ns, ns["V"]) for k, v in reads.items()} if null else reads
    return ns, rows


def summ(rows, ns):
    W = ns["W"]
    return {"median_E_Sh_over_W": est.median([r["E_Sh"] for r in rows]) / W,
            "median_E_RL_over_W": est.median([r["E_RL"] for r in rows]) / W,
            "rank_floor_seeds": sum(1 for r in rows if r["p"] <= 1.0 / 11 + 1e-12),
            "estimated": est.estimated(rows),
            "L1": est.estimated(rows) and est.clause_L1(rows, ns),
            "L3": est.estimated(rows) and est.clause_L3(rows, ns),
            "median_Z": est.median([r["Z"] for r in rows if r["Z"] is not None]),
            "median_G": est.median([r["G"] for r in rows])}


t0 = time.time()
out = {"mode": MODE}

if MODE == "pc16":
    # RT-6n: PC-16b (key at M = 16 on three primes, flat) and PC-16c (mixtures
    # rho 1, 0.9, 0.8) as z_ladder reads them (uniform path), many replicates.
    R = int(sys.argv[5])
    reps = []
    for rep in range(R):
        flat, dec = {}, {}
        for l, rho in ((L13, 1.0), (L19, 0.9), (L23, 0.8)):
            fns = {"key": lambda p, e, U, rng, l=l: syn.key_labels(p, l, 16)}
            if rho < 1.0:
                fns["mix"] = lambda p, e, U, rng, l=l, rho=rho: syn.mixture_np(syn.key_labels(p, l, 16), U, 16, rho, rng)
            ns, rows = measure(l, 1, l, 16, range(10), fns, "pc16-%d" % rep)
            flat[("Z-%d" % l, 16)] = {"rows": rows["key"], "null": ns}
            dec[("Z-%d" % l, 16)] = {"rows": rows.get("mix", rows["key"]), "null": ns}
        keys = [("Z-%d" % l, 16) for l in (L13, L19, L23)]
        vf = est.classify_family(flat, keys, LOG2)
        vd = est.classify_family(dec, keys, LOG2)
        reps.append({"PC16b": vf["verdict"], "PC16b_slopes": vf["L2"]["slopes"],
                     "PC16c": vd["verdict"], "PC16c_slopes": vd["L2"]["slopes"],
                     "medZ_key": [est.median([r["Z"] for r in flat[k]["rows"]]) for k in keys],
                     "medZ_mix": [est.median([r["Z"] for r in dec[k]["rows"]]) for k in keys]})
    out["replicates"] = reps
    nb = sum(1 for r in reps if not (r["PC16b"] == "LEAD"))
    nc = sum(1 for r in reps if r["PC16c"] == "LEAD")
    sb = [x for r in reps for x in r["PC16b_slopes"]]
    sc = [x for r in reps for x in r["PC16c_slopes"]]
    out["summary"] = {"R": R, "PC16b_fail_count": nb, "PC16c_fail_count(LEAD)": nc,
                      "PC16b_slope_mean": float(np.mean(sb)), "PC16b_slope_sd": float(np.std(sb)),
                      "PC16b_P_slope_negative": float(np.mean(np.array(sb) < 0)),
                      "PC16c_slope_mean": float(np.mean(sc)), "PC16c_slope_sd": float(np.std(sc)),
                      "PC16c_P_slope_nonnegative": float(np.mean(np.array(sc) >= 0)),
                      "medZ_key_mean_by_cell": [float(np.mean([r["medZ_key"][i] for r in reps])) for i in range(3)],
                      "medZ_mix_mean_by_cell": [float(np.mean([r["medZ_mix"][i] for r in reps])) for i in range(3)]}

elif MODE == "floors":
    # RT-7: the resolving floor of the planted key mixture per (l, M),
    # (a) uniform path exactly as z_ladder (Z/l', unstratified, uniform null,
    # L1 and L3), and (b) the curve-cell path (Z/(4 l'), strata i mod 4,
    # stratified shuffles, exact-saturated null): the NEG-relevant floor (L3)
    # and the LEAD-relevant floor (L1 and L3), for the exact-free mixture
    # (key on the l'-part) and the exact-carrying mixture 4 t + e.
    grid = [(L13, 16), (L13, 8), (L19, 64), (L19, 16), (L23, 128), (L23, 32), (L23, 16)]
    sel = sys.argv[5].split(",") if len(sys.argv) > 5 else None
    res = {}
    for l, M in grid:
        if sel and ("%d@%d" % (l, M)) not in sel:
            continue
        mixf = {("mix%g" % r): (lambda p, e, U, rng, l=l, M=M, r=r: syn.mixture_np(syn.key_labels(p, l, M), U, M, r, rng)) for r in RHOS}
        nsu, ru = measure(l, 1, l, M, range(10), mixf, "floor-u")
        nss, rs = measure(4 * l, 4, l, M, range(10), mixf, "floor-s")
        xcf = {("xc%g" % r): (lambda p, e, U, rng, l=l, M=M, r=r: 4 * syn.mixture_np(syn.key_labels(p, l, M // 4), U, M // 4, r, rng) + e) for r in RHOS}
        _, rx = measure(4 * l, 4, l, M, range(10), xcf, "floor-s")  # same streams and null seeds as nss
        def floor_of(rows, ns, prefix, need_l1):
            f = None
            for r in RHOS:
                rr = rows[prefix + "%g" % r]
                ok = est.clause_L3(rr, ns) and ((not need_l1) or est.clause_L1(rr, ns))
                if ok:
                    f = r
                else:
                    break
            return f
        res["%d@%d" % (l, M)] = {
            "uniform_path": {"null": {"q50": nsu["q50"], "W": nsu["W"], "medV": est.median(nsu["V"])},
                             "floor_L1_and_L3": floor_of(ru, nsu, "mix", True),
                             "per_rho": {k: summ(v, nsu) for k, v in ru.items()}},
            "curve_cell_path": {"null": {"q50": nss["q50"], "W": nss["W"], "medV": est.median(nss["V"])},
                                "exact_free_floor_L3_NEG_relevant": floor_of(rs, nss, "mix", False),
                                "exact_free_floor_L1_and_L3_LEAD_relevant": floor_of(rs, nss, "mix", True),
                                "exact_carrying_floor_L3": floor_of(rx, nss, "xc", False),
                                "exact_carrying_floor_L1_and_L3": floor_of(rx, nss, "xc", True),
                                "per_rho_exact_free": {k: summ(v, nss) for k, v in rs.items()},
                                "per_rho_exact_carrying": {k: summ(v, nss) for k, v in rx.items()}}}
        print("%d@%d" % (l, M), res["%d@%d" % (l, M)]["uniform_path"]["floor_L1_and_L3"],
              {k: v for k, v in res["%d@%d" % (l, M)]["curve_cell_path"].items() if "floor" in k}, round(time.time() - t0), flush=True)
    out["floors"] = res

elif MODE == "lead":
    # RT-5: planted filters on the three lead shapes Z/(4 l'), M = 16, 64, 128,
    # read on the curve-cell path, classified by est.classify_family.
    # Calibration: E_Sh / (3 W) as a function of rho (rounded-key mixtures).
    R = int(sys.argv[5])
    shapes = [(L13, 16), (L19, 64), (L23, 128)]
    cal_r = (0.15, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 0.85, 1.0)
    fam_fns = {
        "XF": lambda l, M, r: (lambda p, e, U, rng: syn.mixture_np(rkey(p, l, M), U, M, r, rng)),
        "XC": lambda l, M, r: (lambda p, e, U, rng: 4 * syn.mixture_np(rkey(p, l, M // 4), U, M // 4, r, rng) + e),
    }
    cal = {}
    for l, M in shapes:
        fns = {"%s%g" % (f, r): fam_fns[f](l, M, r) for f in fam_fns for r in cal_r}
        ns, rows = measure(4 * l, 4, l, M, range(4), fns, "lead-cal")
        cal[(l, M)] = {"W": ns["W"], "medV": est.median(ns["V"]), "q50": ns["q50"],
                       "curve": {k: est.median([x["E_Sh"] for x in v]) / (3 * ns["W"]) for k, v in rows.items()},
                       "curveRL": {k: est.median([x["E_RL"] for x in v]) / (3 * ns["W"]) for k, v in rows.items()}}
        print("cal", l, M, {k: round(v, 2) for k, v in cal[(l, M)]["curve"].items()}, round(time.time() - t0), flush=True)

    def rho_for(l, M, f, target):
        xs = list(cal_r)
        ys = [cal[(l, M)]["curve"]["%s%g" % (f, r)] for r in xs]
        if target >= ys[-1]:
            return None
        if target <= ys[0]:
            return xs[0]
        for i in range(1, len(xs)):
            if ys[i] >= target:
                a, b = ys[i - 1], ys[i]
                return xs[i - 1] + (xs[i] - xs[i - 1]) * (target - a) / (b - a) if b > a else xs[i]
        return None

    plans = {}
    for f in ("XF", "XC"):
        for c in (1.0, 2.0, 4.0):
            plans["%s_flatW_x%g" % (f, c)] = [(l, M, rho_for(l, M, f, c)) for l, M in shapes]
        plans["%s_growing_x1_1.5_2" % f] = [(l, M, rho_for(l, M, f, c)) for (l, M), c in zip(shapes, (1.0, 1.5, 2.0))]
        plans["%s_growing_x2_3_4" % f] = [(l, M, rho_for(l, M, f, c)) for (l, M), c in zip(shapes, (2.0, 3.0, 4.0))]
        plans["%s_key_rho1" % f] = [(l, M, 1.0) for l, M in shapes]
    out["calibration"] = {"%d@%d" % k: v for k, v in cal.items()}
    out["plans"] = {k: [(l, M, r) for l, M, r in v] for k, v in plans.items()}
    evals = {k: [] for k in plans}
    for rep in range(R):
        cells = {k: {} for k in plans}
        for l, M in shapes:
            fns = {}
            for k, v in plans.items():
                rr = [r for (ll, MM, r) in v if ll == l][0]
                if rr is None:
                    continue
                fns[k] = fam_fns[k[:2]](l, M, rr)
            ns, rows = measure(4 * l, 4, l, M, range(10), fns, "lead-ev-%d" % rep)
            for k in fns:
                cells[k][("SYN-%d" % l, M)] = {"rows": rows[k], "null": ns}
        keys = [("SYN-%d" % l, M) for l, M in shapes]
        for k in plans:
            if len(cells[k]) < 3:
                evals[k].append({"verdict": "NOT-PLANTABLE"})
                continue
            v = est.classify_family(cells[k], keys, LOG2)
            evals[k].append({"verdict": v["verdict"], "per_cell": {str(kk): vv for kk, vv in v["per_cell"].items()},
                             "L2_holds": v["L2"]["holds"] if v["L2"] else None,
                             "E_Sh_over_3W": [est.median([x["E_Sh"] for x in cells[k][kk]["rows"]]) / (3 * cells[k][kk]["null"]["W"]) for kk in keys],
                             "E_RL_over_3W": [est.median([x["E_RL"] for x in cells[k][kk]["rows"]]) / (3 * cells[k][kk]["null"]["W"]) for kk in keys],
                             "medZ": [est.median([x["Z"] for x in cells[k][kk]["rows"]]) for kk in keys]})
        print("rep", rep, {k: evals[k][-1]["verdict"] for k in evals}, round(time.time() - t0), flush=True)
    out["evaluations"] = evals
    out["summary"] = {k: {vv: sum(1 for e in v if e["verdict"] == vv) for vv in ("LEAD", "ART-RES", "NEG", "NOT-ESTIMATED", "NOT-PLANTABLE")} for k, v in evals.items()}

elif MODE == "heurb2":
    # RT-9: HEUR-B2's held-out tests (CODE-FAM heur_b2_held_out, with its
    # HELD_OUT_TESTS constant pointed at the synthetic shape names) on labels
    # with F1's marginal law: (A) marginal only, (B) marginal tied to the E/2E
    # bit (XCO1 law), (C) marginal only on the fitting shapes and a rounded-key
    # label carrying F1's marginal by quantile transform on the held-out shapes.
    shapes = {"SYN-K13": (L13, 13, (16, 8)), "SYN-K19": (L19, 19, (64, 16)),
              "SYN-K23": (L23, 23, (128, 32, 16)), "SYN-K41": (L41, 41, (16,))}
    fam.HELD_OUT_TESTS = (
        ("ladder", ("SYN-K13", "SYN-K19"), None, ("SYN-K23",), None),
        ("fixed16", ("SYN-K13", "SYN-K19", "SYN-K23"), 16, ("SYN-K41",), 16),
    )

    def quantile_key(p, l, n, M):
        # F1's marginal by quantile transform of the key position u = (i mod l) / l
        from math import comb
        cdf = np.cumsum([comb(n, w) for w in range(n + 1)]) / float(2 ** n)
        u = (p % l) / float(l)
        w = np.searchsorted(cdf, u, side="right")
        return syn.weight_buckets(n, M)[np.minimum(w, n)]

    outs = {}
    for cid, (l, n, Ms) in shapes.items():
        outs[cid] = {}
        for M in Ms:
            fns = {"A_F1marginal": lambda p, e, U, rng, n=n, M=M: syn.f1_marginal_np(U, n, M, rng),
                   "B_F1marginal_parity": lambda p, e, U, rng, n=n, M=M: syn.xco1_np(U, n, M, e, rng)}
            if cid in ("SYN-K23", "SYN-K41"):
                fns["C_heldout_excess"] = lambda p, e, U, rng, l=l, n=n, M=M: quantile_key(p, l, n, M)
            else:
                fns["C_heldout_excess"] = lambda p, e, U, rng, n=n, M=M: syn.f1_marginal_np(U, n, M, rng)
            ns, rows = measure(4 * l, 4, l, M, range(10), fns, "heurb2")
            for k, v in rows.items():
                outs[cid][(k, M)] = {"rows": v, "null": ns}
            print(cid, M, {k: summ(v, ns)["L3"] for k, v in rows.items()}, round(time.time() - t0), flush=True)
    hb = fam.heur_b2_held_out(outs)
    out["heur_b2_held_out"] = hb
    out["per_cell"] = {cid: {"%s@%d" % k: summ(v["rows"], v["null"]) for k, v in o.items()} for cid, o in outs.items()}

